'use client';

/**
 * Sections — SRS §14.3 "Classes" (which lists Sections), §33's "Sections", checklist row 4.4.
 *
 * ## §33 lists this as a screen; the API has no collection behind it
 *
 * There is no `GET /sections`. A section belongs to a class and is reached at
 * `GET /classes/{id}/sections` — the same shape as the plan sub-screens on the platform surface,
 * where §33 names a screen the API models as part of something else.
 *
 * The resolution here is a class picker rather than a recorded mismatch, because unlike Features
 * this one **has a vocabulary to pick from**: `/classes` is a real list, and "sections of a class"
 * is a question an administrator actually asks. Choosing the class is not a workaround; it is the
 * question the endpoint answers.
 *
 * The chosen class lives in the URL (`?class=7`), so the screen is linkable and survives a reload —
 * the same reasoning as the tabs in `components/tabs.tsx`.
 *
 * ## Two requests, and the second waits for the first
 *
 * The class list loads unconditionally. The sections load only once a class is chosen, and
 * `useCollection` needs a path, so the panel that fetches them is a separate component that is not
 * rendered until there is a class to fetch for. Passing a placeholder path would fire a request for
 * `/classes/undefined/sections` on every first render.
 */

import { Suspense, useCallback, useEffect, useMemo, useState } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';

import { ApiError, api } from '@/lib/apiClient';
import { useAuth } from '@/lib/auth';
import { EXPLAINED_CODES, useCollection } from '@/lib/useCollection';
import type { Refusal } from '@/lib/useCollection';
import type { FormEvent } from 'react';
import {
  CheckboxField,
  Field,
  Notice,
  SelectField,
  focusFirstInvalidField,
  SubmitButton,
  FilterBar,
  FilterSelect,
} from '@/components/form';
import { useRowAction } from '@/lib/useRowAction';
import { Icon } from '@/components/icon';
import { ConfirmDialog, Modal } from '@/components/overlay';
import { useToast } from '@/components/toast';
import {
  Column,
  DataTable,
  EmptyNotice,
  ErrorNotice,
  LoadingBlock,
  PageHeader,
  RefusalNotice,
  StatusBadge,
} from '@/components/table';

interface ClassRow {
  id: number;
  name: string;
  code: string | null;
}

interface SectionRow {
  id: number;
  name: string;
  class_id: number;
  class_teacher_id: number | null;
  capacity: number | null;
  room: string | null;
  is_active: boolean;
}

/**
 * A teacher as `GET /teachers` returns them — the same five fields `classes/new` reads for its picker.
 *
 * ## Why this screen fetches them at all
 *
 * `SectionRow` used to declare `classTeacher?: { first_name, last_name }` and render it.
 * `classes.service.listSections()` is `db.Section.findAll({ where, order })` with **no `include`**,
 * so that association never arrives: the branch was dead and every assigned section fell through to
 * `teacher #12`, which is a number that names nothing an administrator can look up.
 *
 * The sibling `classes/page.tsx` met the same gap and answered it by showing presence — Assigned /
 * Unassigned — with the reasoning written out. That is right for a catalogue of classes, where the
 * question is which ones still need somebody. It is too thin here: a sections table exists to say who
 * takes which section, and \Assigned\ does not answer that.
 *
 * So the names are resolved the way `lib/useSchoolNames` resolves schools — one request, mapped by
 * id, falling back to the id it replaced. `classes/new` already loads exactly this list for its
 * picker, so it is a request the surface already makes.
 */
interface TeacherOption {
  id: number;
  first_name: string;
  last_name: string | null;
}

function SectionsPanel({ classId }: { classId: number }) {
  const { can } = useAuth();

  /*
   * No pagination: `/classes/{id}/sections` takes only `school_id`, because a class has a handful of
   * sections rather than a page of them. Rendering a pager for a list that cannot page would promise
   * a control that does nothing.
   *
   * And therefore NOT `useCollection`, which this used to call. That hook reads the **paginated**
   * envelope — `setRows(result.data ?? [])` — but `classes.controller.js:51` answers
   * `ApiResponse.ok(res, { sections: rows })`, so `rows` became the wrapper object. `rows.length
   * === 0` then evaluated `undefined === 0`, skipping the empty branch, and `DataTable` called
   * `.map` on an object: **`rows.map is not a function`, on every class**, replacing the whole page
   * with Next's default error screen. `timetable/new/page.tsx` already reads this same endpoint
   * correctly as `{ sections }`.
   *
   * The four states are kept by hand rather than inherited, because the hook that owns them is the
   * wrong shape for this endpoint. `EXPLAINED_CODES` is imported from the hook rather than copied.
   */
  const [rows, setRows] = useState<SectionRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [refusal, setRefusal] = useState<Refusal | null>(null);
  const [attempt, setAttempt] = useState(0);
  const [adding, setAdding] = useState(false);

  /*
   * Teacher names, by id. Loaded once for the panel and never blocking the sections themselves — a
   * failure here leaves the column showing ids, which is exactly what it showed before, so the table
   * is never held up or broken by a decoration.
   */
  const [teacherNames, setTeacherNames] = useState<Map<number, string>>(new Map());

  useEffect(() => {
    const controller = new AbortController();
    (async () => {
      try {
        const page = await api.page<TeacherOption[]>('/teachers', {
          query: { limit: 100 },
          signal: controller.signal,
        });
        if (controller.signal.aborted) return;
        setTeacherNames(
          new Map(
            page.data.map((teacher) => [
              teacher.id,
              [teacher.first_name, teacher.last_name].filter(Boolean).join(' '),
            ])
          )
        );
      } catch {
        /* Swallowed on purpose: see above. */
      }
    })();
    return () => controller.abort();
  }, []);
  const reload = useCallback(() => setAttempt((n) => n + 1), []);

  useEffect(() => {
    const controller = new AbortController();
    setLoading(true);
    setError(null);
    setRefusal(null);

    (async () => {
      try {
        const result = await api.get<{ sections: SectionRow[] }>(
          `/classes/${classId}/sections`,
          { signal: controller.signal }
        );
        if (controller.signal.aborted) return;
        setRows(result.sections ?? []);
      } catch (caught) {
        if (controller.signal.aborted) return;
        setRows([]);
        if (caught instanceof ApiError && EXPLAINED_CODES.has(caught.code)) {
          setRefusal({ code: caught.code, message: caught.message });
        } else if (caught instanceof ApiError) {
          setError(caught.message);
        } else if ((caught as Error)?.name !== 'AbortError') {
          setError('Could not reach the server. Check your connection and try again.');
        }
      } finally {
        if (!controller.signal.aborted) setLoading(false);
      }
    })();

    return () => controller.abort();
  }, [classId, attempt]);

  /* Hoisted above the columns, which now need it — the row actions are gated on the same key. */
  const mayManage = can('classes.manage');

  const [editing, setEditing] = useState<SectionRow | null>(null);

  /*
   * A section with students enrolled is refused by the service with a 409, and `useRowAction` keeps
   * that message inside the dialog — where the answer is "retire it instead", which the edit form
   * above offers.
   */
  const remove = useRowAction<SectionRow>({
    perform: (row) => api.delete(`/classes/${classId}/sections/${row.id}`),
    success: (row) => `Section ${row.name} removed`,
    failure: 'Could not remove that section',
    onDone: reload,
  });

  const columns = useMemo<Column<SectionRow>[]>(() => {
    const base: Column<SectionRow>[] = [
      { key: 'name', header: 'Section', cell: (row) => <span className="font-medium">{row.name}</span> },
      {
        key: 'teacher',
        header: 'Class teacher',
        cell: (row) => {
          if (row.class_teacher_id === null) {
            return <span className="text-muted-soft">unassigned</span>;
          }
          const named = teacherNames.get(row.class_teacher_id);
          /* The id is the fallback, not the answer — it is what this column used to always show. */
          return named ?? <span className="text-muted-soft">teacher #{row.class_teacher_id}</span>;
        },
      },
      {
        key: 'capacity',
        header: 'Capacity',
        numeric: true,
        cell: (row) => row.capacity ?? <span className="text-muted-soft">—</span>,
      },
      { key: 'room', header: 'Room', cell: (row) => row.room ?? <span className="text-muted-soft">—</span> },
      { key: 'active', header: 'Status', cell: (row) => <StatusBadge status={row.is_active ? 'active' : 'inactive'} /> },
    ];

    /*
     * The two routes that had no caller.
     *
     * `PATCH` and `DELETE /classes/:id/sections/:sectionId` are both mounted behind `classes.manage`
     * and neither was reachable: a section could be added and then never renamed, never given a
     * room, never assigned a teacher, and never retired. The Add dialog collects three of the six
     * fields the update schema accepts, so even a section created here could not be completed.
     */
    if (!mayManage) return base;

    return [
      ...base,
      {
        key: 'actions',
        header: 'Actions',
        cell: (row) => (
          <span className="flex flex-wrap gap-1">
            <button type="button" onClick={() => setEditing(row)} className="btn btn-ghost btn-sm">
              Edit
            </button>
            <button type="button" onClick={() => remove.ask(row)} className="btn btn-ghost btn-sm">
              <Icon name="trash" size={14} />
              Remove
            </button>
          </span>
        ),
      },
    ];
  /* The names arrive after the first render; without this the column freezes on the fallback. */
  }, [teacherNames, mayManage, remove]);

  if (refusal) return <RefusalNotice refusal={refusal} />;
  if (error) return <ErrorNotice message={error} onRetry={reload} />;
  /* Skeleton on the first load only; a refetch after adding a section dims the table in place. */
  if (loading && rows.length === 0) return <LoadingBlock label="Loading sections…" />;

  const addButton = mayManage ? (
    <button type="button" className="btn btn-primary" onClick={() => setAdding(true)}>
      <Icon name="plus" size={15} />
      Add section
    </button>
  ) : null;

  const dialog = (
    <>
      <AddSectionDialog
        classId={classId}
        open={adding}
        onClose={() => setAdding(false)}
        onCreated={() => {
          setAdding(false);
          reload();
        }}
      />

      <EditSectionDialog
        classId={classId}
        section={editing}
        teacherNames={teacherNames}
        onClose={() => setEditing(null)}
        onSaved={() => {
          setEditing(null);
          reload();
        }}
      />

      <ConfirmDialog
        open={remove.target !== null}
        onCancel={remove.cancel}
        onConfirm={() => remove.confirm()}
        title={`Remove section ${remove.target?.name ?? ''}?`}
        description={
          remove.conflict ??
          'The row is removed outright — sections carry no deleted state. If students are enrolled in it the removal is refused; retire it with the Active switch instead, which keeps the record and takes it off new timetables.'
        }
        confirmLabel="Remove section"
      />
    </>
  );

  /*
   * The empty state carries the action.
   *
   * This used to `return <EmptyNotice>` before reaching the button, so a class with **no sections at
   * all** — the one case where adding one is the only thing you would want to do — offered nothing.
   * The button was rendered only once at least one section already existed.
   */
  if (rows.length === 0) {
    return (
      <>
        <EmptyNotice icon="layers" title="No sections yet" action={addButton}>
          {mayManage
            ? 'A section divides a class into groups, each with its own teacher and room.'
            : 'This class has no sections yet. An administrator adds them.'}
        </EmptyNotice>
        {dialog}
      </>
    );
  }

  return (
    <>
      {addButton ? <div className="mb-3">{addButton}</div> : null}
      <DataTable columns={columns} rows={rows} rowKey={(row) => row.id} caption="Sections of the selected class" busy={loading} />
      {dialog}
    </>
  );
}

/**
 * Add one section to a class — `POST /classes/:id/sections`.
 *
 * Only `name` is required by `createSection`; `capacity` and `room` are the two optional fields worth
 * asking for at creation, because they are what makes a section distinguishable from its siblings.
 * `class_teacher_id` is **not** collected: it takes a teacher id, this screen has no teacher list
 * loaded, and fetching one to populate a picker would make the dialog depend on a second endpoint to
 * offer a field the endpoint does not require. It is set from the section's own edit path.
 *
 * `class_id` is deliberately not sent — the schema declares it `forbiddenField('"class_id" is the
 * path parameter')`, so sending it is a 422.
 */
function AddSectionDialog({
  classId,
  open,
  onClose,
  onCreated,
}: {
  classId: number;
  open: boolean;
  onClose: () => void;
  onCreated: () => void;
}) {
  const { success } = useToast();
  const [name, setName] = useState('');
  const [capacity, setCapacity] = useState('');
  const [room, setRoom] = useState('');
  const [busy, setBusy] = useState(false);
  const [failure, setFailure] = useState<string | null>(null);
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});

  useEffect(() => {
    if (!open) return;
    setName('');
    setCapacity('');
    setRoom('');
    setBusy(false);
    setFailure(null);
    setFieldErrors({});
  }, [open]);

  const submit = async (event: React.FormEvent) => {
    event.preventDefault();
    setBusy(true);
    setFailure(null);
    setFieldErrors({});

    try {
      await api.post(`/classes/${classId}/sections`, {
        name: name.trim(),
        /* Left off entirely rather than sent empty: both are `.allow(null)`, not `.allow('')`. */
        capacity: capacity === '' ? undefined : Number(capacity),
        room: room.trim() || undefined,
      });
      success(`Section ${name.trim()} added`);
      onCreated();
    } catch (caught) {
      if (!(caught instanceof ApiError)) throw caught;
      const perField = caught.fieldErrors();
      if (Object.keys(perField).length > 0) {
        setFieldErrors(perField);
        focusFirstInvalidField();
      } else {
        setFailure(caught.message);
      }
    } finally {
      setBusy(false);
    }
  };

  return (
    <Modal
      open={open}
      onClose={onClose}
      busy={busy}
      size="sm"
      title="Add a section"
      description="Sections divide a class into groups that are taught and marked separately."
      footer={
        <>
          <button type="button" className="btn btn-secondary" onClick={onClose} disabled={busy}>
            Cancel
          </button>
          <SubmitButton form="add-section" busy={busy} busyLabel="Adding…">
            Add section
          </SubmitButton>
        </>
      }
    >
      <form id="add-section" onSubmit={submit} className="space-y-4">
        {failure ? <Notice tone="error">{failure}</Notice> : null}

        <Field
          id="section-name"
          label="Name"
          required
          maxLength={60}
          value={name}
          error={fieldErrors.name}
          onChange={(event) => setName(event.target.value)}
          placeholder="A"
          hint="Usually a letter or a short word. It has to be unique within the class."
        />

        <div className="grid gap-4 sm:grid-cols-2">
          <Field
            id="section-capacity"
            label="Capacity"
            type="number"
            min="0"
            step="1"
            inputMode="numeric"
            value={capacity}
            error={fieldErrors.capacity}
            onChange={(event) => setCapacity(event.target.value)}
            hint="Optional."
          />
          <Field
            id="section-room"
            label="Room"
            maxLength={60}
            value={room}
            error={fieldErrors.room}
            onChange={(event) => setRoom(event.target.value)}
            hint="Optional."
          />
        </div>
      </form>
    </Modal>
  );
}

/**
 * `PATCH /classes/:id/sections/:sectionId`.
 *
 * ## It collects the whole update schema, unlike the Add dialog
 *
 * `AddSectionDialog` asks for three fields — name, capacity, room — because those are what a section
 * needs to exist. The update schema accepts **six**, and the three it adds are the ones a section
 * acquires later: the class teacher, and `is_active`, which is how a section is retired. Offering
 * only what creation offered would leave half the record permanently unreachable, which is the
 * shape of the gap this dialog closes.
 *
 * `class_id` is `forbiddenField('"class_id" is the path parameter')` on the schema, so a section
 * cannot be moved between classes here — and nothing pretends otherwise.
 *
 * ## The teacher picker is fed from the names the panel already loaded
 *
 * `SectionsPanel` fetches `/teachers` once for its Class-teacher column and keeps an id → name map.
 * Reading that rather than fetching again means the dialog opens with no request of its own, and a
 * teacher the map could not resolve simply is not offered — which is honest, because it is a teacher
 * the panel cannot name either.
 */
function EditSectionDialog({
  classId,
  section,
  teacherNames,
  onClose,
  onSaved,
}: {
  classId: number;
  section: SectionRow | null;
  teacherNames: Map<number, string>;
  onClose: () => void;
  onSaved: () => void;
}) {
  const { success } = useToast();
  const [name, setName] = useState('');
  const [capacity, setCapacity] = useState('');
  const [room, setRoom] = useState('');
  const [teacherId, setTeacherId] = useState('');
  const [isActive, setIsActive] = useState(true);
  const [reason, setReason] = useState('');
  const [busy, setBusy] = useState(false);
  const [failure, setFailure] = useState<string | null>(null);
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});

  /* Seeded from the row every time a different section is opened. */
  useEffect(() => {
    if (!section) return;
    setName(section.name);
    setCapacity(section.capacity === null ? '' : String(section.capacity));
    setRoom(section.room ?? '');
    setTeacherId(section.class_teacher_id === null ? '' : String(section.class_teacher_id));
    setIsActive(section.is_active);
    setReason('');
    setBusy(false);
    setFailure(null);
    setFieldErrors({});
  }, [section]);

  async function submit(event: FormEvent) {
    event.preventDefault();
    if (!section) return;
    setBusy(true);
    setFailure(null);
    setFieldErrors({});

    try {
      /*
       * The whole editable set, not a diff. `.min(1)` would accept a diff, but computing one means
       * deciding whether a cleared field is "set to null" or "unchanged" — and getting that wrong
       * silently drops an edit. A blank capacity or room goes as `null`, which is what clearing one
       * means.
       */
      await api.patch(`/classes/${classId}/sections/${section.id}`, {
        name,
        capacity: capacity.trim() ? Number(capacity) : null,
        room: room.trim() || null,
        class_teacher_id: teacherId ? Number(teacherId) : null,
        is_active: isActive,
        reason: reason.trim() || undefined,
      });
      success(`Section ${name} updated`);
      onSaved();
    } catch (caught) {
      if (!(caught instanceof ApiError)) throw caught;
      const perField = caught.fieldErrors();
      setFieldErrors(perField);
      setFailure(Object.keys(perField).length ? null : caught.message);
      if (Object.keys(perField).length) focusFirstInvalidField();
    } finally {
      setBusy(false);
    }
  }

  return (
    <Modal
      open={section !== null}
      onClose={onClose}
      title={section ? `Edit section ${section.name}` : 'Edit section'}
      description="A section cannot be moved to another class — that is fixed by the path it lives at."
      busy={busy}
      footer={
        <>
          <button type="button" onClick={onClose} disabled={busy} className="btn btn-secondary">
            Cancel
          </button>
          <SubmitButton form="edit-section" busy={busy} busyLabel="Saving…">
            Save changes
          </SubmitButton>
        </>
      }
    >
      <form id="edit-section" onSubmit={submit} className="space-y-4" noValidate>
        {failure ? <Notice tone="error">{failure}</Notice> : null}

        <Field
          id="edit-section-name"
          label="Name"
          required
          maxLength={60}
          value={name}
          error={fieldErrors.name}
          onChange={(event) => setName(event.target.value)}
          hint="Unique within the class."
        />

        <SelectField
          id="edit-section-teacher"
          label="Class teacher"
          value={teacherId}
          error={fieldErrors.class_teacher_id}
          onChange={(event) => setTeacherId(event.target.value)}
          hint="Optional. Only teachers of this school can be named; one from another school is refused."
        >
          <option value="">Nobody named</option>
          {[...teacherNames.entries()].map(([id, label]) => (
            <option key={id} value={id}>
              {label}
            </option>
          ))}
        </SelectField>

        <div className="grid gap-4 sm:grid-cols-2">
          <Field
            id="edit-section-capacity"
            label="Capacity"
            type="number"
            min="0"
            step="1"
            inputMode="numeric"
            value={capacity}
            error={fieldErrors.capacity}
            onChange={(event) => setCapacity(event.target.value)}
            hint="Optional. Clear it for no limit."
          />
          <Field
            id="edit-section-room"
            label="Room"
            maxLength={60}
            value={room}
            error={fieldErrors.room}
            onChange={(event) => setRoom(event.target.value)}
            hint="Optional."
          />
        </div>

        <CheckboxField
          id="edit-section-active"
          label="Active"
          checked={isActive}
          error={fieldErrors.is_active}
          onChange={(event) => setIsActive(event.target.checked)}
          hint="Retiring a section keeps it and its records, and takes it off new timetables and registers. This is the alternative to removing it, and the only one available once students have been enrolled."
        />

        <Field
          id="edit-section-reason"
          label="Reason"
          maxLength={255}
          value={reason}
          error={fieldErrors.reason}
          onChange={(event) => setReason(event.target.value)}
          hint="Optional. Recorded against this edit."
        />
      </form>
    </Modal>
  );
}

/** `PAGINATION.MAX_LIMIT` — the most one page of the class picker can hold. */
const CLASS_LIMIT = 100;

function SectionsScreen() {
  const router = useRouter();
  const params = useSearchParams();
  /* An empty `?class=` is no choice at all, as it was before; only something typed there is judged. */
  const selected = params.get('class')?.trim() || null;

  /*
   * Parsed once, and only a positive integer counts as a class. The id arrives from the URL, which
   * the header invites people to share and bookmark — so a hand-edited `?class=abc` is a real entry
   * path, and it used to become `Number('abc')`, a request to `/classes/NaN/sections`, and an error
   * whose Try again could only fail the same way. `null` means no usable class, whatever the URL said.
   */
  const parsed = selected === null ? NaN : Number(selected);
  const classId = Number.isInteger(parsed) && parsed > 0 ? parsed : null;

  const classes = useCollection<ClassRow>('/classes', useMemo(() => ({ limit: CLASS_LIMIT }), []));

  /*
   * The picker holds one page, and a school with several sessions' classes can pass a hundred. It
   * used to stop there without a word, so a class past the cut simply was not in the list and its
   * sections could not be reached. The total is read and the shortfall said.
   */
  const classTotal = classes.meta?.total ?? classes.rows.length;
  const truncated = classTotal > classes.rows.length;

  /*
   * A well-formed id the list does not contain. When the list is complete that is a class that no
   * longer exists — deleted, or never this school's — and fetching its sections would only 404 behind
   * a Try again that cannot help. When the list is a first page, it may simply be past the cut, so the
   * sections are still fetched.
   */
  const unknownClass =
    classId !== null &&
    !classes.loading &&
    !truncated &&
    !classes.rows.some((row) => row.id === classId);

  return (
    <div>
      <PageHeader
        title="Sections"
        description="A section belongs to a class, so choose the class first."
      />

      {/*
        * Not a filter — this picker is what the screen is *for*, since there is no `GET /sections`
        * and the whole table below depends on it. It uses the filter row's shape anyway, so it lines
        * up with every other list screen, and keeps its visible label because "Choose a class…"
        * names an action rather than the thing being chosen. No clear button: clearing it would
        * leave the screen with nothing to show.
        */}
      <FilterBar>
        <FilterSelect
          id="class-picker"
          label="Class"
          labelVisible
          value={classId !== null ? String(classId) : ''}
          onChange={(value) => {
            const next = new URLSearchParams(params.toString());
            if (value) next.set('class', value);
            else next.delete('class');
            router.replace(`?${next.toString()}`, { scroll: false });
          }}
          disabled={classes.loading || classes.rows.length === 0}
          className="sm:min-w-64"
        >
          <option value="">Choose a class…</option>
          {classes.rows.map((row) => (
            <option key={row.id} value={row.id}>
              {row.name}
              {row.code ? ` (${row.code})` : ''}
            </option>
          ))}
        </FilterSelect>
      </FilterBar>

      {truncated ? (
        <p className="-mt-2 mb-4 text-sm text-muted">
          The first {classes.rows.length} of {classTotal} classes. A page cannot hold more, so a class
          past these is not in the list.
        </p>
      ) : null}

      {/*
        * The class list's own failures are surfaced here rather than swallowed. A refusal on
        * `/classes` means this screen cannot work at all, and saying "choose a class" over an empty
        * picker would describe the symptom instead of the cause.
        */}
      {classes.refusal ? (
        <RefusalNotice refusal={classes.refusal} />
      ) : classes.error ? (
        <ErrorNotice message={classes.error} onRetry={classes.reload} />
      ) : classes.loading && classes.rows.length === 0 ? (
        <LoadingBlock />
      ) : classes.rows.length === 0 ? (
        <EmptyNotice>No classes exist yet, so there are no sections to show.</EmptyNotice>
      ) : selected !== null && classId === null ? (
        <EmptyNotice>This link does not name a class. Choose one above to see its sections.</EmptyNotice>
      ) : unknownClass ? (
        <EmptyNotice>
          The class in this link is not one of this school’s classes — it may have been deleted.
          Choose one above to see its sections.
        </EmptyNotice>
      ) : classId !== null ? (
        <SectionsPanel classId={classId} />
      ) : (
        <EmptyNotice>Choose a class above to see its sections.</EmptyNotice>
      )}
    </div>
  );
}

export default function SectionsPage() {
  return (
    <Suspense fallback={<LoadingBlock />}>
      <SectionsScreen />
    </Suspense>
  );
}
